contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint collectAmount, uint unlockTime) public payable {
        require(address(this).balance >= putAmount);

        // Snapshot the caller's holder balance before any state-changing call.
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // Add funds. unlockTime is chosen in the past so the funds are immediately collectable.
        c.Put{value: putAmount}(unlockTime);

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // Collect all funds that were just deposited (and only those) to measure the return.
        c.Collect{value: 0}(putAmount);

        (, uint finalBal) = c.Acc(address(this));

        // General rule: after a Put of putAmount, the recorded balance grew by exactly
        // putAmount; a successful Collect of putAmount returned that amount (more Ether
        // left c than entered it by putAmount) and reset the balance back to its prior value.
        assert(
            afterBal == beforeBal + putAmount &&
            finalBal == beforeBal &&
            address(c).balance + putAmount == address(this).balance + 0
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint putAmount) public payable {
        require(address(this).balance >= putAmount);
        require(putAmount > 0);

        (, uint beforeBal) = c.Acc(address(this));
        uint beforeC = address(c).balance;

        c.Put{value: putAmount}(0);

        (, uint afterBal) = c.Acc(address(this));
        uint afterC = address(c).balance;

        assert(
            afterBal == beforeBal + putAmount &&
            afterC >= beforeC + putAmount
        );
    }

