}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        c.Put{value: putAmount}(0);

        (, uint beforeBal) = c.Acc(address(this));
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        (, uint afterBal) = c.Acc(address(this));

        if (beforeBal >= 1 ether && collectAmount <= beforeBal) {
            assert(!reverted && afterBal == beforeBal - collectAmount);
        } else {
            assert(reverted && afterBal == beforeBal);
        }
    }

    receive() external payable {}
}

