contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _am) public payable {
        require(address(this).balance >= 1 ether);
        c.Put{value: 1 ether}(0);

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        bool shouldSucceed = beforeBalance >= c.MinSum() && beforeBalance >= _am && block.timestamp > beforeUnlock;
        if (shouldSucceed) {
            assert(!reverted);
            assert(afterBalance == beforeBalance - _am);
            assert(afterContractBal + _am == beforeContractBal);
        } else {
            assert(reverted);
            assert(afterBalance == beforeBalance);
            assert(afterContractBal == beforeContractBal);
        }
    }

    receive() external payable {}
}

